struct NativeDirectoryMembershipReferences;
// An acquisition may record edges; a consumer receives only the const owner.
// Borrowing this adapter never changes reference counts or extends lifetimes.
struct NativeDirectoryMembershipAccess {
    NativeDirectoryMembershipAccess() = default;
    NativeDirectoryMembershipAccess(NativeDirectoryMembershipReferences& owner) : retained(&owner), recorder(&owner) {}
    NativeDirectoryMembershipAccess(NativeDirectoryMembershipReferences* owner) : retained(owner), recorder(owner) {}
    NativeDirectoryMembershipAccess(const NativeDirectoryMembershipReferences* owner) : retained(owner) {}
    explicit operator bool() const { return retained != nullptr; }
    auto capture(MountPoint* mount, uint64_t expected, File*& out) const -> int;
    auto current(uint64_t expected) const -> bool;

   private:
    const NativeDirectoryMembershipReferences* retained = nullptr;
    NativeDirectoryMembershipReferences* recorder = nullptr;
};
